"""Editorial and interactive layer for the second website pass."""
from html import escape
import re
from tink_growth import growth_plan
from phase_budgets import investment_budget_summary

def a(label, href, cls='text-link'):
    return f'<a class="{cls}" href="{href}">{label}<span aria-hidden="true"> ↗</span></a>'

def faq(title, entries):
    return '<section class="section answer-section"><div class="wrap answer-grid"><div><span class="eyebrow">Before you take the next step</span><h2>'+title+'</h2></div><div>'+''.join('<details><summary>'+q+'</summary><p>'+v+'</p></details>' for q,v in entries)+'</div></div></section>'

def tabs(key, labels, panels, title):
    buttons=''.join(f'<button type="button" role="tab" id="{key}-tab-{i}" aria-controls="{key}-panel-{i}" aria-selected="{str(i==0).lower()}" tabindex="{0 if i==0 else -1}"><span class="choice-count">0{i+1}</span>{label}</button>' for i,label in enumerate(labels))
    content=''.join(f'<section role="tabpanel" id="{key}-panel-{i}" aria-labelledby="{key}-tab-{i}" class="choice-panel"'+(' hidden' if i else '')+'>'+p+'</section>' for i,p in enumerate(panels))
    return f'<div class="choice-browser" data-choice-tabs><div class="choice-tabs" role="tablist" aria-label="{title}">{buttons}</div><div class="choice-content">{content}</div></div>'

def sample(kind, quote, path, result, href, label, drawing):
    return f'<div class="sample-project"><div class="sample-art" aria-hidden="true">{drawing}</div><div class="sample-copy"><span class="eyebrow">Illustrative project / {kind}</span><h3>{quote}</h3><dl><div><dt>Start with</dt><dd>{path}</dd></div><div><dt>Work toward</dt><dd>{result}</dd></div></dl>{a(label,href)}</div></div>'

BRACKET='<svg viewBox="0 0 420 310"><path class="draft-grid" d="M30 70H390M30 130H390M30 190H390M30 250H390M90 30V280M150 30V280M210 30V280M270 30V280M330 30V280"/><path class="solid-shape" d="M118 58h64v126h130v64H118Z"/><circle class="cutout" cx="150" cy="92" r="13"/><circle class="cutout" cx="278" cy="216" r="13"/><path class="draft-line" d="M92 58H62v190h30M118 270v17h194v-17M182 115h105l40-41"/><circle class="draft-dot" cx="182" cy="115" r="5"/><text x="261" y="61">Sketch → part</text></svg>'
