def enhance(name, body):
    if name=='home':
        old='<div class="readiness-line"><span>See what is changing.</span><span>Build the capability.</span><span>Move forward together.</span></div>'
        new='''<div class="mission-flow" data-reveal><div><span class="flow-kicker">River Tech</span><strong>Develop the person.</strong><p>Faith. Human arts. Agentic technology.</p></div><span class="flow-connector" aria-hidden="true">→</span><div><span class="flow-kicker">Tink Town</span><strong>Put ability to work.</strong><p>Ideas. Enterprise. Community service.</p></div><span class="flow-connector" aria-hidden="true">→</span><div><span class="flow-kicker">Our shared purpose</span><strong>Build a better future.</strong><p>Capable people, rooted in this place.</p></div></div>'''
        body=body.replace(old,new)
        # Keep the beloved opening; shorten a repeated abstract passage.
        body=body.replace('New technology can unsettle a business. It can also open doors. Our approach is to meet change directly: understand what matters, learn the tools and find a useful way forward.','We believe preparation turns uncertainty into possibility. Learn what is changing. Build the skills. Put them to work on something that matters.')
        marker='<section class="section pathways"'
        evidence='''<section class="section evidence-section"><div class="wrap evidence-layout"><figure class="evidence-photo"><img src="assets/images/photos/Music_Class.jpg" alt="River Tech students playing instruments together" loading="lazy"><figcaption>River Tech in practice · School photography</figcaption></figure><div><span class="eyebrow">A real beginning. An ambitious next chapter.</span><h2>It starts<br>with people.</h2><p>Our school concept is already in practice in Post Falls. Tink Town is the next venture: a place to take human ability further, through useful work and community.</p><div class="evidence-actions">'''+a('See the school in action','https://www.youtube.com/watch?v=3gG10NDjFV4')+a('Meet the founders','pages/story.html')+'''</div></div></div></section>'''
        body=body.replace(marker,evidence+marker)
        body=body.replace("<div class=\"wrap values\">",'<div class="wrap values" data-reveal>')
        # A personal invitation appears only after the main story and three main routes.
        marker='<section><div class="wrap values"'
        personal='''<section class="belong-invitation"><div class="wrap"><div><span class="eyebrow">There is room for you here</span><h2>An idea. A calling.<br>A place to begin.</h2></div><div><p>Maybe you are not bringing a business or a building. Maybe you are bringing a question about what you could become.</p>'''+a('Find your people. Dream big.','pages/dream-big.html')+'''</div></div></section>'''
        body=body.replace(marker,personal+marker)
    elif name=='river-tech':
        body=body.replace('src="../assets/images/photos/Girls_Building_Robot.jpg" alt="Two students collaborating on a robotics project"','src="../assets/images/photos/a3f9bc_243d758660d543e3abf63cf7a31825db_mv2.jpg" alt="River Tech children exploring nature beside a lake"').replace('Making technology a hands-on discipline.','Learning reaches beyond the classroom.')
        body=body.replace('<img src="../assets/images/photos/Music_Class.jpg" alt="Music class at River Tech in Post Falls" loading="lazy">','<div class="school-location"><span class="eyebrow">Where the idea took root</span><strong>Post Falls.</strong><span>Idaho</span><p>The first River Tech school</p></div>')
        match=re.search(r'<section class="section tint-section" id="pillars">.*?</section>',body,re.S)
        if match:
            panels=[]
            data=[('Human arts','A voice. A presence. A contribution.','Music and performance give students practice in preparation, expression, teamwork and showing up for others. These human skills belong beside technical ability.','a3f9bc_44477dc306c54bf09c883358ce143cd7_mv2.jpg','River Tech students performing in a play','Rehearse, listen, refine and contribute to a shared performance.'),('Agentic technology','Build with the tools changing work.','Coding, robotics, design and AI belong in a practical learning experience. The aim is to understand a problem, choose a useful tool, check the result and take responsibility for the work.','Girls_Building_Robot.jpg','Students working together on a robot','Design, build, test and explain the choices behind a project.'),('A strong foundation','Knowledge to think with.','Mathematics, language, science, history and Bible provide the knowledge students need to reason, communicate and make sound judgments. Technology is more useful when the person using it has something to bring.','Math_Tutoring.jpg','A teacher helping a student with mathematics','Work toward understanding, with room to practice and master the essentials.')]
            for label,title,text,img,alt,practice in data:
                panels.append(f'<figure><img src="../assets/images/photos/{img}" alt="{alt}" loading="lazy"></figure><div class="learning-copy"><span class="eyebrow">{label}</span><h3>{title}</h3><p>{text}</p><p class="practice-note"><strong>In practice</strong> {practice}</p></div>')
            replacement='<section class="section learning-section" id="pillars"><div class="wrap"><div class="section-head"><div><span class="eyebrow">Three pillars, held together</span><h2>Develop the whole person.</h2></div><p>Explore what each pillar contributes—and why none stands alone.</p></div>'+tabs('learning',['Human arts','Agentic technology','Core academics'],panels,'The three learning pillars')+'</div></section>'
            body=body[:match.start()]+replacement+body[match.end():]
        body=body.replace('<div class="steps">','<div class="steps">')
        marker='<section class="cta-section">'
        extra=faq('Could this be<br>your community’s school?',[
            ('What would we be responsible for?','Your organization runs the school, including staffing, tuition, budgets, premises and local requirements. River Tech LLC provides the agreed brand and concept rights, founders’ consultation and oversight of the agreed concept standards.'),
            ('What kind of space are we considering?','Our working plan starts with six classrooms averaging about 15 students each, plus space to eat, gather and work. The property guide includes a room-by-room plan and a preferred search range of 8,000–9,000 square feet. '+a('Explore the space plan','investing.html#property')),
            ('Can a college start with a course rather than a school?','Yes. A workshop, course module or short course can be a starting point for collaboration. The college determines academic credit and qualifications. '+a('Explore college partnerships','community.html#colleges'))])
        body=body.replace(marker,extra+marker)
    elif name=='tink-town':
        # Replace abstract examples with visual worked scenarios; no client-result claims.
        match=re.search(r'<section class="section"><div class="wrap"><span class="eyebrow">What could that look like\?</span>.*?</section></div></div></section>',body,re.S)
        # Instead of matching nested tab sections, use the following known section boundary.
        start=body.find('<section class="section"><div class="wrap"><span class="eyebrow">What could that look like?</span>')
        end=body.find('<section class="section tink-next-paths">',start)
        if start>=0 and end>=0:
            panels=[sample('Design & fabrication','“Can you help us make this?”','A sketch, broken part or digital model. Work through dimensions, material and the job it must do.','A design and prototype you can test: a bracket, fixture, enclosure, sign or useful custom part.','investing.html#projects','Explore fabrication projects',BRACKET),sample('AI & automation','“There has to be a better way.”','One repeated task: collecting enquiries, preparing quotes, moving information or following up.','A small workflow your team can review and test before wider use. Compare time, quality and effort.','investing.html#training','Explore practical AI training',FLOW),sample('Creative & print','“Our work deserves a better story.”','Your audience, message and existing website or marketing materials.','A clearer visual identity across a website, video, flyers, posters or signs. Design and production can work together.','investing.html#projects','Explore creative projects',POSTER)]
            block='<section class="section project-studio"><div class="wrap"><div class="section-head"><div><span class="eyebrow">From a real question to useful work</span><h2>What could we make possible?</h2></div><p>Three examples of the work Tink Town is being developed to do. These are illustrative projects, not completed client case studies.</p></div>'+tabs('project',['Make something','Improve a workflow','Tell your story'],panels,'Explore possible Tink Town projects')+'</div></section>'
            body=body[:start]+block+body[end:]
        marker='<section class="bridge-section"><div class="wrap bridge-inner"><div><span class="eyebrow">The River Tech connection</span>'
        visit='''<section class="section gathering-section"><div class="wrap gathering-layout"><div class="gathering-words"><span class="eyebrow">The place matters, too</span><h2>Come for a coffee.<br>Leave with a possibility.</h2><p class="lead">A welcoming third place where conversation, useful work and new ideas have room to meet.</p><p>The plan brings a café and small stage together with maker supplies, workspaces and a separated production workshop. A business meeting could become a prototype. An evening gathering could become a friendship.</p>'''+a('Discover Dream Big','dream-big.html')+'''</div><div class="place-map" aria-label="Tink Town planned spaces"><div class="map-front"><span>Gather</span><strong>Café + small stage</strong><small>Coffee, conversation, events</small></div><div><span>Discover</span><strong>Maker shop</strong><small>Robotics &amp; modelling supplies</small></div><div><span>Create</span><strong>Work together</strong><small>Design, ideas &amp; collaboration</small></div><div class="map-work"><span>Make</span><strong>Production workshop</strong><small>Fabrication, print &amp; prototypes</small></div><p>Concept zones · not an architectural floor plan</p></div></div></section>'''
        body=body.replace(marker,visit+marker)
        closing=body.rfind('<section class="cta-section">')
        if closing>=0:
            body=body[:closing]+growth_plan()+body[closing:]
        else:
            body+=growth_plan()
    elif name=='dream-big':
        # Keep the approved warm invitation; bring it into a distinctive editorial composition.
        body=body.replace('<section class="page-hero blue">','<section class="page-hero blue dream-hero">',1)
        start=body.find('<section class="section tint-section" id="next-step">')
        end=body.find('<section class="cta-section">',start)
        if start>=0 and end>=0:
            panels=[ '<span class="eyebrow">When you are looking for direction</span><h3>You can start with a question.</h3><p>What gives you energy? What have people always come to you for? What need in your community stays on your mind?</p><p>Purpose coaching can help you name your strengths, explore possibilities and choose one small step to try.</p>'+a('Let’s explore your direction','contact.html?topic=dream-big'), '<span class="eyebrow">When you have an idea</span><h3>Give it room to take shape.</h3><p>Bring the thing you keep thinking about. A business, a project, a ministry or a better way to solve a familiar problem.</p><p>Work toward a clear first experiment: who it serves, what you need to learn and what you could make or test next.</p>'+a('Tell us about your idea','contact.html?topic=dream-big'), '<span class="eyebrow">When you are ready to build</span><h3>Find the people for the next step.</h3><p>You might need a skill, a collaborator, a tool or someone to help you stay focused.</p><p>Connect the idea to practical work, through learning, making and a community that wants to see you grow.</p>'+a('Start the conversation','contact.html?topic=dream-big')]
            new='<section class="section purpose-section" id="next-step"><div class="wrap"><div class="section-head"><div><span class="eyebrow">Fan your calling into flame</span><h2>Where are you<br>starting from?</h2></div><p>You do not need a finished plan to belong here. Choose what sounds like you.</p></div>'+tabs('purpose',['I’m finding my direction','I have an idea','I’m ready to build'],panels,'Find your first step')+'</div></section>'
            body=body[:start]+new+body[end:]
        body=body.replace('<section class="section" id="belong">','<section class="section belonging-section" id="belong">')
        # The upcoming offer is clearly distinguished from a currently open venue.
        body=body.replace('<p class="inline-note">Part of the Tink Town launch plan. The location, gathering schedule and coaching arrangements are being developed.</p>','<div class="launch-note"><span class="status-dot" aria-hidden="true"></span><p><strong>Help shape the first chapter.</strong> The Tink Town location, weekly gathering schedule and coaching arrangements are in development. Your conversation can help shape what comes first.</p></div>')
    elif name=='partnerships':
        # A useful entry page, not another long description of every destination.
        hero=body[:body.index('<nav class="jump-nav"')]
        rows=[('Business owners','Bring a challenge. Find a useful way forward.','Explore a prototype, a workflow improvement, practical staff training or a clearer way to tell your story.','investing.html#projects','Explore projects'),('Schools & colleges','Connect learning with real contribution.','Start a River Tech school, explore a course partnership or connect students with practical projects and experienced people.','river-tech.html#licensing','Explore school partnerships'),('Churches & community','Build on what we already value.','Combine local knowledge, Christian faith and practical capability through workshops, service projects and shared gatherings.','community.html','Explore church & community'),('People with a calling','You do not have to begin alone.','Bring your questions or your idea. Discover the people, encouragement and practical next step that can help it grow.','dream-big.html','Discover Dream Big')]
        starting_points=[
            ('One task, part or communication challenge that would make a difference if solved.','Define a useful first result, then agree scope, cost and how to judge it.'),
            ('Your community, students and educational aims. Tell us whether you mean a whole school or a course.','Explore the model, local responsibilities and what a sensible first collaboration could be.'),
            ('The people you serve, an idea for a gathering or a practical local need.','Shape a workshop, service project or event around a shared purpose.'),
            ('Your questions, interests or the idea you keep returning to. A formal proposal is not needed.','Find a conversation, a learning opportunity or a small experiment that helps you move forward.')]
        panels=[f'<span class="eyebrow">{label}</span><h3>{title}</h3><p>{text}</p><dl class="partner-start"><div><dt>Bring to the conversation</dt><dd>{starting_points[i][0]}</dd></div><div><dt>A practical first step</dt><dd>{starting_points[i][1]}</dd></div></dl>'+a(link,href) for i,(label,title,text,href,link) in enumerate(rows)]
        panels[1]+=a('Explore college courses','community.html#colleges')
        body=hero+'<section class="section partner-chooser" id="find-your-fit"><div class="wrap"><div class="section-head"><div><span class="eyebrow">One shared purpose. Different contributions.</span><h2>What brings you here?</h2></div><p>Start with the people you serve and the work you want to make possible.</p></div>'+tabs('partner',['My business','My school or college','My church or community','My own next step'],panels,'Find a partnership')+'</div></section>'
        body+='''<section class="section partner-exchange"><div class="wrap"><span class="eyebrow">A relationship with substance</span><h2>What could each of us bring?</h2><div class="exchange-lines"><div><span>Your contribution</span><p>A real problem. Local knowledge. A skill. A space. An opportunity.</p></div><span class="exchange-mark" aria-hidden="true">↔</span><div><span>Our contribution</span><p>Learning. Design. Useful technology. Creative work. People to build with.</p></div></div><p>We agree on the first useful piece of work, what each side contributes, and any costs, recognition or responsibilities. There is no standard fee or automatic access to schools.</p><div class="journey-links">'''+a('Property, equipment & capital','investing.html')+a('Discuss a partnership','contact.html?topic=business')+'</div></div></section>'
        # Keep existing incoming anchors as real, meaningful destinations.
        body=body.replace('id="find-your-fit"','id="businesses"').replace('class="section partner-exchange"','class="section partner-exchange" id="relationship"')
        body=body.replace('id="partner-panel-1"','id="partner-panel-1" data-route="schools"').replace('id="partner-panel-2"','id="partner-panel-2" data-route="community"')
        body+=faq('Start with a<br>clear understanding.',[('Do all partnerships look the same?','No. A commercial project, a church workshop and an equipment lease serve different purposes. Each needs an arrangement that fits the work.'),('Can a partner work with students?','Activities involving a school require that school operator’s agreement, appropriate supervision and clear responsibilities. Possibilities include workshops, field trips, mentoring, practical projects and access to specialized equipment.'),
            ('Can a business receive recognition or promote an offer?','That can be part of an agreed exchange. The participating school or organization approves the recognition, promotion and offers appropriate for its audience. A partnership does not create unrestricted access to students or families.'),('Could we contribute a building or equipment?','Yes. Our practical guide includes space plans, equipment capabilities and the arrangements we would need to discuss. '+a('See the seven opportunities','investing.html'))])
        body+='<section class="cta-section"><div class="wrap cta-inner"><h2>Start with one useful thing.</h2>'+a('Tell us what you have in mind','contact.html?topic=business','button white')+'</div></section>'
    elif name=='community':
        # Keep approved content; make the three audiences browsable in one place.
        captures=[]
        for key in ['churches','colleges','community-groups']:
            m=re.search(r'<section class="section(?: tint-section)?" id="'+key+r'">.*?</section>',body,re.S)
            if m: captures.append((key,m.group(0)))
        if len(captures)==3:
            first=body.index(captures[0][1]); last=body.index(captures[-1][1])+len(captures[-1][1])
            buttons=''.join(f'<button type="button" role="tab" id="community-tab-{i}" aria-controls="{key}" aria-selected="{str(i==0).lower()}" tabindex="{0 if i==0 else -1}" data-community="{key}">{label}</button>' for i,((key,_),label) in enumerate(zip(captures,['Churches','Colleges','Community groups'])))
            panels=''.join(part.replace('id="'+key+'"','id="'+key+f'" role="tabpanel" aria-labelledby="community-tab-{i}"'+(' hidden' if i else ''),1) for i,(key,part) in enumerate(captures))
            body=body[:first]+'<div class="community-browser" data-community-tabs><div class="community-tabbar"><div class="wrap" role="tablist" aria-label="Explore church and community partnerships">'+buttons+'</div></div>'+panels+'</div>'+body[last:]
        body=body.replace('Church & community','Church & community',1)
    elif name=='investing':
        body=body.replace('Explore the seven opportunities<span class="arrow" aria-hidden="true">↗</span></a>', 'Explore the seven opportunities<span class="arrow" aria-hidden="true">↗</span></a><a class="text-link investment-budget-shortcut" href="#phase-funding">Compare phase budgets <span aria-hidden="true">↓</span></a>',1)
        marker='<section class="section opportunity-section"'
        guide='''<section class="funding-guide"><div class="wrap"><span class="eyebrow">Two ways to take part</span><div class="funding-guide-grid"><a href="#property"><span>Provide the foundation</span><strong>Property · Equipment · Lending</strong><small>Help create the place and the capability.</small></a><a href="#projects"><span>Put talent to work</span><strong>Projects · Hiring · Training · Events</strong><small>Bring useful work into the community.</small></a></div></div></section>'''
        impact='''<section class="section local-impact" id="local-impact" aria-labelledby="local-impact-title"><div class="wrap intro-grid"><div><span class="eyebrow">Meaningful capital. Local impact.</span><h2 id="local-impact-title">A smaller investment.<br>A meaningful impact.</h2></div><div><p class="lead">A commitment in the tens of thousands could help Tink Town take a meaningful first step: equipping a small workspace, adding useful production tools or launching services for local businesses.</p><p>For someone with a larger investment portfolio, that could be a relatively small allocation. For a young local enterprise, it could be the difference between an idea on paper and useful work getting done.</p><p>And the impact can happen close to home: local talent developing, businesses adapting and people finding practical help with problems that matter to them.</p><p class="impact-line">A smaller share of your portfolio.<br>A substantial part of our beginning.</p><a class="text-link" href="tink-town.html#growth">See how Tink Town can start small <span aria-hidden="true">↗</span></a></div></div></section>'''
        body=body.replace(marker,guide+marker)
        marker='<section class="bridge-section">'
        sequence='''<section class="section launch-sequence"><div class="wrap"><div class="section-head"><div><span class="eyebrow">Building the first Tink Town</span><h2>A practical order<br>for an ambitious idea.</h2></div><p>Start with the work, prepare what it needs and grow from the results. Phase budgets are estimates; opening dates and funding commitments are still to be agreed.</p></div><ol class="launch-track"><li><span>01 / Define</span><h3>Choose the first work.</h3><p>Identify local needs, a useful starting offer and the people needed to deliver it.</p></li><li><span>02 / Prepare</span><h3>Fit the place to the plan.</h3><p>Match premises, equipment and approvals to the work. Agree the operating and funding arrangements.</p></li><li><span>03 / Prove</span><h3>Open, learn and improve.</h3><p>Begin with work we can deliver, measure the results and expand where demand supports it.</p></li></ol></div></section>'''
        body=body.replace(marker,sequence+marker,1)
        closing=body.rfind('<section class="cta-section">')
        body=body[:closing]+impact+investment_budget_summary()+body[closing:] if closing>=0 else body+impact+investment_budget_summary()
    elif name=='story':
        body=body.replace('<div class="timeline">','<div class="timeline timeline-journey" data-reveal>')
        body=body.replace('<section class="section tint-section"><div class="wrap"><span class="eyebrow">The thread through it all</span>','<section class="section tint-section story-conviction"><div class="wrap"><span class="eyebrow">The thread through it all</span>')
        marker='<section class="culture-statement"'
        more='''<section class="story-evidence"><div class="wrap"><div><span class="eyebrow">See where it began</span><h2>The school is<br>already a living story.</h2><p>Meet the people and see the learning behind the River Tech concept.</p></div><a class="film-link" href="https://www.youtube.com/watch?v=3gG10NDjFV4"><span class="play-symbol" aria-hidden="true">▶</span><span>Watch the River Tech introduction<small>Opens on YouTube</small></span></a></div></section>'''
        body=body.replace(marker,more+marker)
    elif name=='contact':
        body=body.replace('<form id="inquiry-form">','<form id="inquiry-form"><p class="form-intro">You do not need a finished proposal. A question, a problem or a first idea is enough.</p>')
        marker='<div class="aside-block"><h3>Looking for the school?</h3>'
        nextsteps='''<div class="aside-block next-conversation"><h3>What happens next?</h3><ol><li><strong>Tell us a little.</strong><span>Choose a topic and describe what you have in mind.</span></li><li><strong>Review your email.</strong><span>The form prepares a draft in your own email app.</span></li><li><strong>Start the conversation.</strong><span>Send when ready. We can then explore fit and the next useful step.</span></li></ol></div>'''
        body=body.replace(marker,nextsteps+marker)
    return body
